effect.shader:
void main() {
    float r = texture(inputImg, acScreenNorm + vec2(chroma, 0.0)).r;
    float g = texture(inputImg, acScreenNorm).g;
    float b = texture(inputImg, acScreenNorm - vec2(chroma, 0.0)).b;
    float a = texture(inputImg, acScreenNorm).a;
    vec3 cor = vec3(r, g, b);

    float linha = 0.5 + 0.5 * sin(acScreenNorm.y * lineDensity * 3.14159);
    cor *= 1.0 - lineStrength * (1.0 - linha);

    float barra = fract(acScreenNorm.y + acTime * rollSpeed);
    float ganho = smoothstep(0.02, 0.0, abs(barra - 0.5) - 0.48);
    cor += ganho * 0.08;

    fragColor = vec4(cor, a);
}
